<div class="page-heading"><div><div class="eyebrow">CHÃO DE FÁBRICA</div><h1>Ordens de produção</h1><p>Fluxo produtivo, responsáveis, prioridades e prazos.</p></div><div class="page-actions"><a href="<?=e(url('production',['new'=>1]))?>#editor" class="btn-aurora"><?=svg_icon('plus',16)?> Nova ordem</a></div></div>
<?php if(allow(['production'])):?><details class="panel editor" id="editor" <?=($edit||isset($_GET['new']))?'open':''?>><summary><?=$edit?'Editar ordem de produção':'Cadastrar ordem de produção'?></summary><div class="editor-inner"><form method="post" action="<?=e(url('workorders.save'))?>"><?=csrf_field()?><input type="hidden" name="_back" value="production"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid cols-3"><div class="field span-2"><label>Serviço / Descrição *</label><input name="title" required value="<?=e($edit['title']??'')?>" placeholder="Ex.: Produção de armários da cozinha"></div><div class="field"><label>Projeto *</label><select name="project_id" required><option value="">Selecione...</option><?php foreach($projects as $p):?><option value="<?=e($p['id'])?>" <?=($edit['project_id']??'')==$p['id']?'selected':''?>><?=e($p['title'])?></option><?php endforeach;?></select></div><div class="field"><label>Prioridade</label><select name="priority"><?php foreach(['low','normal','high'] as $s):?><option value="<?=$s?>" <?=($edit['priority']??'normal')===$s?'selected':''?>><?=e(label_status($s))?></option><?php endforeach;?></select></div><div class="field"><label>Responsável</label><select name="assigned_to"><option value="">A definir</option><?php foreach($staff as $s):?><option value="<?=e($s['id'])?>" <?=($edit['assigned_to']??'')==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Prazo</label><input name="due_date" type="date" value="<?=e($edit['due_date']??'')?>"></div><div class="field span-3"><label>Instruções de produção</label><textarea name="notes"><?=e($edit['notes']??'')?></textarea></div></div><div class="form-footer"><button class="btn-aurora">Salvar ordem</button><a href="<?=e(url('production'))?>" class="btn-aurora btn-outline-aurora">Cancelar</a></div></form></div></details><?php endif;?>
<?php if($history):?><div class="panel panel-pad" style="margin-bottom:21px"><h2>Histórico de etapas</h2><div style="margin-top:11px"><?php foreach($history as $event):?><div style="display:flex;gap:13px;padding:11px 0;border-bottom:1px solid var(--line)"><span class="text-accent"><?=svg_icon('check')?></span><div><strong><?=e(label_status($event['new_status']))?></strong><p class="hint"><?=e($event['user_name'])?> · <?=e(date_time_br($event['created_at']))?></p></div></div><?php endforeach;?></div></div><?php endif;?>
<div class="panel"><div class="panel-header"><div><h2>Fila de produção</h2><p>Altere a etapa para manter o progresso atualizado.</p></div><span class="tag"><?=count($orders)?> ordens</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ordem</th><th>Projeto / Cliente</th><th>Responsável</th><th>Prazo</th><th>Prioridade</th><th>Etapa</th><th>Ações</th></tr></thead><tbody>
<?php foreach($orders as $o):?><tr><td><strong><?=e($o['code'])?></strong><small><?=e($o['title'])?></small></td><td><?=e($o['project_title'])?><small><?=e($o['customer_name'])?></small></td><td><?=e($o['assignee']?:'Não definido')?></td><td><?=e(date_br($o['due_date']))?></td><td><span class="status-badge <?=$o['priority']==='high'?'badge-danger':'badge-muted'?>"><?=e(label_status($o['priority']))?></span></td><td><?=status_badge($o['status'])?></td><td><div class="table-actions"><a href="<?=e(url('production',['history'=>$o['id']]))?>" class="btn-aurora btn-outline-aurora btn-sm-aurora">Histórico</a><?php if(allow(['production'])):?><a href="<?=e(url('production',['edit'=>$o['id']]))?>#editor" class="btn-aurora btn-outline-aurora btn-sm-aurora"><?=svg_icon('edit',14)?></a><?php if(!in_array($o['status'],['delivered','cancelled'],true)):?><form action="<?=e(url('workorders.status'))?>" method="post" style="display:flex;gap:5px"><?=csrf_field()?><input type="hidden" name="_back" value="production"><input type="hidden" name="id" value="<?=e($o['id'])?>"><select class="inline-select" name="status" aria-label="Nova etapa"><?php foreach(['queued','cutting','edgebanding','assembly','finishing','ready','delivered','cancelled'] as $s):?><option value="<?=e($s)?>" <?=$o['status']===$s?'selected':''?>><?=e(label_status($s))?></option><?php endforeach;?></select><button type="submit" class="btn-aurora btn-sm-aurora">Atualizar</button></form><?php endif;endif;?></div></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="7" class="empty">Nenhuma ordem de produção cadastrada.</td></tr><?php endif;?></tbody></table></div></div>
